// Matérias-base de Anatomia da grade do 1º e 2º períodos.
// A disciplina é compartilhada pelas turmas do período: vídeos da Cátedra não
// dependem de uma turma ou grupo específico. Preservar matérias já cadastradas.
(function ensureAnatomyForEveryCohort(){
  DB.subjects=DB.subjects||{};
  const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
  for(const [period,name] of [[1,'Anatomía I'],[2,'Anatomía II']]){
    const existing=Object.entries(DB.subjects).some(([key,item])=>{
      const n=normalize(key);
      return Number(item?.period)===period &&
        /^anatomia(?:\s+(?:humana|descriptiva|general))?\s+(?:i|ii|1|2)$/.test(n) &&
        (period===1?/(?:^|\s)(?:i|1)$/.test(n):/(?:^|\s)(?:ii|2)$/.test(n));
    });
    if(existing)continue;
    DB.subjects[name]={
      teacher:'Cátedra de Anatomia',practiceTeacher:'Cátedra de Anatomia',
      mode:'Teoria + Prática',accent:'mint',active:true,period,
      slug:'anatomia-'+period,slides:[],provas:[],audios:[],videos:[],
      pratica:[],complementares:[]
    };
  }
})();

