function renderLibrary(){
  const items=[];
  Object.entries(DB.subjects).forEach(([name,s])=>['slides','provas','audios','videos','pratica','complementares'].forEach(cat=>(s[cat]||[]).forEach(it=>items.push({...it,subject:name,cat}))));
  const filtered = items.filter(it=>!searchTerm || (it.title+' '+it.subject+' '+it.cat).toLowerCase().includes(searchTerm));
  $('page-library').innerHTML=`
  <div class="heading"><div><span class="eyebrow">Biblioteca</span><h1>Todos os materiais</h1><p>Catálogo geral da plataforma e uploads locais temporários.</p></div><div class="heroActions"><button class="btn primary" onclick="$('libUp').click()">Subir arquivo local</button><input id="libUp" class="hidden" type="file" onchange="addLocalLib(this.files[0])"></div></div>
  <div class="cards">
    ${filtered.slice(0,24).map((it,i)=>`<div class="card"><div class="cardHead"><div class="iconWrap">${esc(it.cat[0].toUpperCase())}</div><span class="pill">${esc(it.subject)}</span></div><h3>${esc(it.title)}</h3><p>${esc(it.cat)} · ${esc(it.period||'Geral')} · ${esc(it.kind||'Arquivo')}</p><div class="heroActions" style="margin-top:12px">${it.id?`<button class="btn sm primary" onclick="openDrive('${it.id}')">Abrir</button>`:''}</div></div>`).join('')}
    ${localLib.map((f,i)=>`<div class="card"><div class="cardHead"><div class="iconWrap">L</div><span class="pill violet">Local</span></div><h3>${esc(f.name)}</h3><p>${esc(f.type||'arquivo')} · ${(f.size/1024/1024).toFixed(1)} MB</p><button class="btn sm" onclick="window.open(localLib[${i}].url,'_blank')">Abrir</button></div>`).join('')}
  </div>`
}
