const HUB_LABELS={daily:'Desafio diário',study:'Estudar',questions:'Buscar questões',simulado:'Simulado',flashcards:'Flashcards',apostilas:'Apostilas',pockets:'Pockets (A6)',errors:'Caderno de erros',reinforce:'Reforço do dia',saved:'Salvos e anotações',stats:'Estatísticas',weak:'Pontos fracos',dna:'DNA da prova',mentoring:'Mentoria semanal','study-together':'Estudar junto',ranking:'Ranking'};
const STUDY_KEY='sinusalEditorialStudy';
let STUDY;try{STUDY=JSON.parse(SAFE_STORE.getItem(STUDY_KEY)||'null')||{attempts:[],flashcards:[],pockets:[],saves:[],seconds:0}}catch(e){STUDY={attempts:[],flashcards:[],pockets:[],saves:[],seconds:0}}
let examTimer=null,focusTimer=null,focusStart=0,focusElapsed=0,questionFilter='all',questionSubject='all',flashIndex=0;
function studySave(){SAFE_STORE.setItem(STUDY_KEY,JSON.stringify(STUDY))}
function allQuestions(){return (DB.training?.questions||[]).filter(q=>q.active!==false)}
function attempted(){return STUDY.attempts||[]}
function getQ(id){return allQuestions().find(q=>q.id===id)}
function dayKey(){return new Date().toISOString().slice(0,10)}
function accuracy(){const a=attempted();return a.length?Math.round(a.filter(x=>x.ok).length/a.length*100):0}
function sectionTitle(caption,title,desc='',actions=''){return `<div class="heading"><div><span class="eyebrow">${caption}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${actions}</div>`}
function emptyBox(heading,desc,button=''){return `<div class="glass" style="padding:44px 20px;text-align:center;min-height:210px"><div style="font-size:22px;color:#8e938d;margin-bottom:14px">◌</div><h3 style="font-size:17px">${heading}</h3><p class="soft" style="font-size:11px;line-height:1.75;margin-top:7px">${desc}</p>${button?`<div style="margin-top:17px">${button}</div>`:''}</div>`}
function hubBox(){return $('page-hub')}
function renderHub(page){switch(page){
  case 'daily': return renderDaily();case 'study':return renderStudy();case 'questions':return renderQuestionSearch();case 'simulado':return renderSimulado();case 'flashcards':return renderFlashcards();case 'apostilas':return renderApostilas();case 'pockets':return renderPockets();case 'errors':return renderErrors();case 'reinforce':return renderReinforce();case 'saved':return renderSaved();case 'stats':return renderStats();case 'weak':return renderWeak();case 'dna':return renderDNA();case 'mentoring':return renderMentoring();case 'study-together':return renderStudyTogether();case 'ranking':return renderRanking();default:hubBox().innerHTML=emptyBox('Ambiente em preparação','Escolha uma das opções do menu.');}}
function openFirstSubject(tab='overview'){const first=subjectEntries()[0];if(!first){nav('subjects');return}openSubject(first[0]);setTab(tab)}
function renderDaily(){const a=attempted(),today=dayKey(),done=a.some(x=>x.tag==='daily'&&x.date.slice(0,10)===today);const q=allQuestions()[(new Date().getDate()+new Date().getMonth())%Math.max(1,allQuestions().length)];hubBox().innerHTML=sectionTitle('HOJE · UM DESAFIO','Desafio diário','Um caso ou conceito por dia para manter a revisão ativa.',`<span class="pill green">${done?'Concluído hoje':'Disponível hoje'}</span>`)+(q?`<div class="glass" style="max-width:910px;padding:24px"><span class="eyebrow">${esc(q.subject)} · ${esc(q.period)}</span><h2 style="font-size:22px;line-height:1.35;margin:15px 0">${esc(q.prompt)}</h2>${q.type==='multiple'?`<div class="stack">${(q.options||[]).map(o=>`<button class="answerBtn" onclick="answerDaily('${q.id}',${esc(JSON.stringify(o))})">${esc(o)}</button>`).join('')}</div>`:`<textarea id="dailyAnswer" rows="4" placeholder="Sua resposta..."></textarea><div style="margin-top:10px"><button class="btn primary" onclick="answerDaily('${q.id}',$('dailyAnswer').value)">Confirmar</button></div>`}<div id="dailyFeedback"></div></div>`:emptyBox('Banco vazio','Cadastre questões no administrador.'))}
function answerDaily(id,ans){const q=getQ(id);if(!q)return;const ok=String(ans).trim().toLowerCase()===String(q.answer).trim().toLowerCase();STUDY.attempts.push({id,subject:q.subject,type:q.type,ok,date:new Date().toISOString(),tag:'daily'});studySave();$('dailyFeedback').innerHTML=`<div class="feedback"><b>${ok?'Resposta correta':'Resposta para revisar'}</b><p style="font-size:11px;margin-top:8px">${esc(q.answer)}</p><p class="soft" style="font-size:10px;margin-top:5px">${esc(q.explanation||'')}</p></div>`;toast('Desafio registrado')}
function renderStudy(){const u=user();hubBox().innerHTML=sectionTitle('ESTUDAR · HOJE','Como quer estudar hoje?','Escolha um ambiente; o fluxo mantém o contexto acadêmico do Sinus.')+`<div class="glass" style="padding:22px;background:#20221f!important;color:#fff!important;margin-bottom:16px"><span style="font-family:monospace;font-size:9px;letter-spacing:.12em;opacity:.65">SESSÃO INTELIGENTE</span><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-top:9px"><h2 style="font-size:19px;color:white">Questões do seu semestre, no seu ritmo</h2><button class="btn" onclick="nav('questions')">Explorar questões →</button></div></div><div class="grid3">${[['▥','Matérias','Slides, vídeos, áudios e teoria/prática','subjects'],['◷','Simulado','Uma sequência com tempo de estudo','simulado'],['▱','Flashcards','Revise respostas de forma ativa','flashcards']].map(([i,t,d,p])=>`<button class="card" onclick="nav('${p}')"><div class="iconWrap">${i}</div><h3>${t}</h3><p>${d}</p><span class="eyebrow" style="display:block;margin-top:18px">ABRIR →</span></button>`).join('')}</div><div class="grid2" style="margin-top:14px"><div class="glass adminBlock"><span class="eyebrow">FOCO</span><h3 style="margin:10px 0;font-size:16px">Cronômetro de estudo</h3><div id="focusClock" style="font-size:46px;font-weight:750;letter-spacing:-.07em;margin:14px 0">00:00:00</div><div class="controlRow"><button class="btn primary" onclick="toggleFocus()" id="focusButton">Iniciar</button><button class="btn" onclick="resetFocus()">Zerar</button></div><p class="soft" style="font-size:10px;margin-top:10px">Tempo contabilizado nesta sessão local.</p></div><div class="glass adminBlock"><span class="eyebrow">PERÍODO ATUAL</span><h3 style="font-size:16px;margin:10px 0">${esc(u.period)} · Turma ${esc(u.class)}</h3><p class="soft" style="font-size:11px;line-height:1.8">Seu cronograma e os grupos práticos são mantidos na área de horários. Você também pode consultar todas as grades originais no Drive.</p><button class="btn" style="margin-top:13px" onclick="nav('schedule')">Ver cronograma</button></div></div>`}
function fmtSec(s){s=Math.max(0,Math.floor(s));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0')).join(':')}
function updateFocus(){const e=$('focusClock');if(e)e.textContent=fmtSec(focusElapsed+(focusTimer?(Date.now()-focusStart)/1000:0))}
function toggleFocus(){if(focusTimer){clearInterval(focusTimer);focusTimer=null;focusElapsed+=(Date.now()-focusStart)/1000;if($('focusButton'))$('focusButton').textContent='Continuar';STUDY.seconds=Math.round((STUDY.seconds||0)+focusElapsed);studySave();focusElapsed=0}else{focusStart=Date.now();focusTimer=setInterval(updateFocus,500);if($('focusButton'))$('focusButton').textContent='Pausar'}updateFocus()}
function resetFocus(){if(focusTimer)clearInterval(focusTimer);focusTimer=null;focusElapsed=0;if($('focusButton'))$('focusButton').textContent='Iniciar';updateFocus()}
function renderQuestionSearch(){hubBox().innerHTML=sectionTitle('PRATICAR · BANCO','Buscar questões','Encontre questões pelo enunciado, disciplina ou formato.')+`<div class="glass" style="padding:18px"><input id="qSearch" placeholder="Buscar no enunciado..." oninput="renderSearchRows()"><div class="controlRow" style="margin:11px 0"><select id="qSubject" style="width:auto;min-width:210px" onchange="renderSearchRows()"><option value="all">Todas as matérias</option>${Object.keys(DB.subjects).map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select><select id="qFormat" style="width:auto" onchange="renderSearchRows()"><option value="all">Todos os formatos</option>${(DB.training.types||[]).map(t=>`<option value="${t.id}">${esc(t.label)}</option>`).join('')}</select><button class="btn primary" onclick="startFilteredSearchSession()">Estudar estas questões</button></div><div id="searchRows"></div></div>`;renderSearchRows()}
function searchRows(){const v=($('qSearch')?.value||'').toLowerCase(),subject=$('qSubject')?.value||'all',type=$('qFormat')?.value||'all';return allQuestions().filter(q=>(subject==='all'||subject===q.subject)&&(type==='all'||type===q.type)&&(!v||(q.prompt+' '+q.subject).toLowerCase().includes(v)))}
function renderSearchRows(){const qs=searchRows();$('searchRows').innerHTML=`<div class="eyebrow" style="margin:12px 0">${qs.length} resultado(s) encontrados</div><div class="stack">${qs.map(q=>`<button class="resourceItem" onclick="openQuestionDetail('${q.id}')"><b>${esc(q.prompt)}</b><small>${esc(q.subject)} · ${esc(q.period)} · ${esc(q.type)} →</small></button>`).join('')||emptyBox('Nenhuma questão encontrada','Tente mudar os filtros ou cadastrar questões.')}</div>`}
function openQuestionDetail(id){const q=getQ(id);if(!q)return;openModal('Questão · '+q.subject,`<div style="font-size:13px;font-weight:700;line-height:1.55">${esc(q.prompt)}</div><div style="font-size:11px;margin-top:15px">${(q.options||[]).map(o=>`<div class="quickItem">${esc(o)}</div>`).join('')}<div class="feedback"><b>Resposta esperada: ${esc(q.answer)}</b><p class="soft" style="margin-top:7px">${esc(q.explanation||'')}</p></div></div>`,closeModal)}
function startFilteredSearchSession(){const qs=searchRows();if(!qs.length)return toast('Nenhuma questão neste filtro');startStandaloneExam(qs,'Questões filtradas')}
function renderSimulado(){hubBox().innerHTML=sectionTitle('PRATICAR · SIMULADO','Simulado','Sessão de perguntas do banco existente, com relatório local de acertos.')+`<div class="grid2"><div class="glass adminBlock"><label class="field"><span>Matéria</span><select id="examSubject">${Object.keys(DB.subjects).map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label class="field"><span>Quantidade</span><select id="examCount"><option value="5">5 questões</option><option value="10" selected>10 questões</option><option value="20">20 questões</option><option value="999">Todas disponíveis</option></select></label><button class="btn primary" onclick="startSimulado()">Iniciar simulado</button></div><div class="glass adminBlock"><span class="eyebrow">SEU HISTÓRICO LOCAL</span><h2 style="font-size:42px;margin:14px 0">${attempted().length}</h2><p class="soft" style="font-size:11px">respostas registradas em todas as sessões.</p><div class="eyebrow" style="margin-top:18px">ACERTO ATUAL: ${accuracy()}%</div></div></div>`}
function startSimulado(){const qs=allQuestions().filter(q=>q.subject===$('examSubject').value).sort(()=>Math.random()-.5).slice(0,Number($('examCount').value));if(!qs.length)return toast('Ainda não há questões para essa matéria');startStandaloneExam(qs,'Simulado')}
let activeExam=null;
function startStandaloneExam(questions,title){activeExam={questions,index:0,correct:0,title};nav('simulado');renderStandaloneQuestion()}
function renderStandaloneQuestion(){const e=activeExam;if(!e)return;const q=e.questions[e.index];if(!q){hubBox().innerHTML=sectionTitle('SESSÃO FINALIZADA',e.title,`Resultado: ${e.correct} acertos em ${e.questions.length} questões.`)+`<div class="glass adminBlock"><h2 style="font-size:46px">${Math.round(100*e.correct/e.questions.length)}%</h2><button class="btn primary" onclick="activeExam=null;renderSimulado()">Novo simulado</button><button class="btn" onclick="nav('errors')">Rever erros</button></div>`;activeExam=null;return}hubBox().innerHTML=sectionTitle(e.title,`Questão ${e.index+1} de ${e.questions.length}`)+`<div class="glass adminBlock" style="max-width:900px"><span class="eyebrow">${esc(q.subject)} · ${esc(q.type)}</span><h2 style="font-size:21px;line-height:1.4;margin:15px 0">${esc(q.prompt)}</h2>${q.type==='multiple'?(q.options||[]).map(o=>`<button class="answerBtn" onclick="examAnswer(${esc(JSON.stringify(o))})">${esc(o)}</button>`).join(''):`<textarea id="examAnswer" rows="3" placeholder="Sua resposta..."></textarea><button class="btn primary" onclick="examAnswer($('examAnswer').value)">Responder</button>`}<div id="examFeedback"></div></div>`}
function examAnswer(answer){const q=activeExam.questions[activeExam.index];if(activeExam.answered)return;const ok=String(q.answer).trim().toLowerCase()===String(answer||'').trim().toLowerCase();if(ok)activeExam.correct++;STUDY.attempts.push({id:q.id,subject:q.subject,type:q.type,ok,date:new Date().toISOString(),tag:'exam'});studySave();activeExam.answered=true;$('examFeedback').innerHTML=`<div class="feedback"><b>${ok?'Acertou!':'Revisar esta resposta'}</b><div style="font-size:11px;margin-top:8px">${esc(q.answer)}</div><p class="soft" style="font-size:10px;margin-top:5px">${esc(q.explanation||'')}</p></div><button class="btn primary" style="margin-top:10px" onclick="activeExam.answered=false;activeExam.index++;renderStandaloneQuestion()">${activeExam.index+1>=activeExam.questions.length?'Ver resultado':'Próxima'}</button>`}
function renderFlashcards(){const deck=allQuestions().filter(q=>q.type==='flashcard'||attempted().some(a=>a.id===q.id&&!a.ok));hubBox().innerHTML=sectionTitle('PRATICAR · REVISÃO ESPAÇADA','Flashcards','Vire o cartão e avalie se conseguiu lembrar.')+(deck.length?`<div class="glass" style="padding:22px;max-width:850px"><div class="eyebrow">CARTÃO ${(flashIndex%deck.length)+1} DE ${deck.length}</div><div class="flashBox" id="independentFlash" onclick="revealIndependentFlash()" style="margin-top:16px"><h2 style="font-size:22px">${esc(deck[flashIndex%deck.length].prompt)}</h2></div><div class="controlRow" style="margin-top:13px"><button class="btn" onclick="nextFlashcard('hard')">Ainda não lembrei</button><button class="btn primary" onclick="nextFlashcard('easy')">Lembrei</button><button class="btn" onclick="revealIndependentFlash()">Mostrar resposta</button></div></div>`:emptyBox('Nenhum flashcard ainda','Cadastre flashcards pelo administrador ou responda questões para gerar revisões.',`<button class="btn primary" onclick="nav('questions')">Buscar questões</button>`))}
function revealIndependentFlash(){const deck=allQuestions().filter(q=>q.type==='flashcard'||attempted().some(a=>a.id===q.id&&!a.ok));const q=deck[flashIndex%deck.length];if(!q)return;$('independentFlash').innerHTML=`<div><span class="eyebrow">RESPOSTA</span><h2 style="margin-top:10px">${esc(q.answer)}</h2><p class="soft" style="margin-top:10px;font-size:11px">${esc(q.explanation||'')}</p></div>`}
function nextFlashcard(grade){const deck=allQuestions().filter(q=>q.type==='flashcard'||attempted().some(a=>a.id===q.id&&!a.ok));if(!deck.length)return;const q=deck[flashIndex%deck.length];STUDY.flashcards.push({id:q.id,grade,date:new Date().toISOString()});studySave();flashIndex++;renderFlashcards()}
function renderApostilas(){const files=[];Object.entries(DB.subjects).forEach(([subject,s])=>['slides','complementares','provas'].forEach(kind=>(s[kind]||[]).forEach(f=>files.push({subject,kind,...f}))));hubBox().innerHTML=sectionTitle('ESTUDAR · APOSTILAS','Apostilas de estudo','Materiais já vinculados às disciplinas do Sinus. Os arquivos abrem pelo Drive.')+`<div class="glass adminBlock"><input id="apostSearch" oninput="filterApostilas()" placeholder="Buscar pelo título, matéria ou tipo..."><div id="apostList"></div></div>`;filterApostilas()}
function filterApostilas(){const q=($('apostSearch')?.value||'').toLowerCase();const files=[];Object.entries(DB.subjects).forEach(([subject,s])=>['slides','complementares','provas'].forEach(kind=>(s[kind]||[]).forEach(f=>files.push({subject,kind,...f}))));const f=files.filter(x=>(x.subject+' '+x.title+' '+x.kind).toLowerCase().includes(q));$('apostList').innerHTML=`<div class="eyebrow" style="margin:15px 0">${f.length} documentos</div><div class="stack">${f.slice(0,55).map(x=>`<div class="quickItem"><div><b>${esc(x.title)}</b><div class="soft" style="font-size:9px;margin-top:5px">${esc(x.subject)} · ${esc(x.kind)}</div></div>${x.id?`<button class="btn sm" onclick="openDrive('${x.id}')">Abrir</button>`:`<span class="pill">Sem link</span>`}</div>`).join('')||emptyBox('Nada encontrado','Tente outro título.')}</div>`}
function renderPockets(){hubBox().innerHTML=sectionTitle('ESTUDAR · BOLSO','Pockets (A6)','Notas curtas para revisão rápida ou impressão em formato compacto.',`<button class="btn primary" onclick="newPocket()">Criar pocket</button>`)+`<div class="grid3">${(STUDY.pockets||[]).map((p,i)=>`<div class="glass adminBlock"><span class="eyebrow">Pocket A6 · ${esc(p.subject||'Geral')}</span><h3 style="font-size:16px;margin:11px 0">${esc(p.title)}</h3><p style="font-size:11px;line-height:1.75;white-space:pre-wrap">${esc(p.text)}</p><div class="controlRow" style="margin-top:15px"><button class="btn sm" onclick="printPocket(${i})">Imprimir</button><button class="btn sm" onclick="removePocket(${i})">Excluir</button></div></div>`).join('')||`<div style="grid-column:1/-1">${emptyBox('Você ainda não criou pockets','Crie seu primeiro material de bolso.')}</div>`}</div>`}
function newPocket(){openModal('Novo pocket',`<label class="field"><span>Título</span><input id="poTitle"></label><label class="field"><span>Matéria</span><select id="poSubject">${Object.keys(DB.subjects).map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label class="field"><span>Conteúdo</span><textarea id="poText" rows="8"></textarea></label>`,()=>{STUDY.pockets.unshift({title:$('poTitle').value,subject:$('poSubject').value,text:$('poText').value});studySave();closeModal();renderPockets()})}
function removePocket(i){STUDY.pockets.splice(i,1);studySave();renderPockets()}
function printPocket(i){const p=STUDY.pockets[i];const w=window.open('','_blank');if(!w)return toast('Libere pop-ups para imprimir');w.document.write(`<html><head><title>${esc(p.title)}</title><style>@page{size:A6;margin:12mm}body{font-family:Arial;font-size:11px}h1{font-size:16px}p{white-space:pre-wrap;line-height:1.55}</style></head><body><h1>${esc(p.title)}</h1><p>${esc(p.text)}</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function wrongAttempts(){return attempted().filter(a=>!a.ok).reverse()}
function renderErrors(){const wrong=wrongAttempts();hubBox().innerHTML=sectionTitle('REVISAR · CADERNO','Caderno de erros','Cada resposta errada fica registrada para revisão futura.',`<span class="pill">${wrong.length} erro(s)</span>`)+(wrong.length?`<div class="glass adminBlock"><div class="stack">${wrong.map((a,i)=>{const q=getQ(a.id);return q?`<div class="quickItem"><div><b>${esc(q.prompt)}</b><div class="soft" style="margin-top:5px;font-size:9px">${esc(a.subject)} · ${new Date(a.date).toLocaleDateString()}</div></div><button class="btn sm" onclick="reviewSingleQuestion('${a.id}')">Refazer</button></div>`:''}).join('')}</div></div>`:emptyBox('Nenhum erro registrado','Responda algumas questões para começar a construir seu caderno.',`<button class="btn primary" onclick="nav('questions')">Buscar questões</button>`))}
function reviewSingleQuestion(id){const q=getQ(id);if(!q)return;startStandaloneExam([q],'Revisar erro')}
function renderReinforce(){const ids=[...new Set(wrongAttempts().map(x=>x.id))],qs=ids.map(getQ).filter(Boolean);hubBox().innerHTML=sectionTitle('REVISAR · HOJE','Reforço do dia','Retome os pontos que precisam de mais prática.')+(qs.length?`<div class="glass adminBlock"><h3 style="font-size:18px;margin-bottom:15px">Sua sessão de recuperação</h3><p class="soft" style="font-size:11px">${qs.length} questão(ões) baseadas nos erros anteriores.</p><button class="btn primary" style="margin-top:14px" onclick="startWrongReview()">Revisar meus erros</button></div>`:emptyBox('Tudo em dia','Quando houver erros registrados, aparecerão aqui questões para reforçar.'))}
function startWrongReview(){const ids=[...new Set(wrongAttempts().map(x=>x.id))],qs=ids.map(getQ).filter(Boolean);if(qs.length)startStandaloneExam(qs,'Reforço')}
function renderSaved(){let notes=[];for(const n of Object.keys(DB.subjects)){const t=SAFE_STORE.getItem('note_'+n);if(t&&t.trim())notes.push({subject:n,text:t})}hubBox().innerHTML=sectionTitle('REVISAR · ACERVO PESSOAL','Salvos e anotações','Seu caderno e materiais marcados para revisão.')+`<div class="grid2"><div class="glass adminBlock"><span class="eyebrow">Anotações das matérias</span><div class="stack" style="margin-top:12px">${notes.map(n=>`<div class="quickItem"><div><b>${esc(n.subject)}</b><div class="soft" style="font-size:9px">${esc(n.text.slice(0,110))}</div></div><button class="btn sm" onclick="openSubject(${esc(JSON.stringify(n.subject))});setTab('notebook')">Abrir</button></div>`).join('')||'<p class="soft" style="font-size:11px">Nenhuma nota salva ainda.</p>'}</div></div><div class="glass adminBlock"><span class="eyebrow">Seus pockets</span><div class="stack" style="margin-top:12px">${(STUDY.pockets||[]).map(x=>`<div class="quickItem"><b>${esc(x.title)}</b><span>${esc(x.subject)}</span></div>`).join('')||'<p class="soft" style="font-size:11px">Sem pockets.</p>'}</div><button class="btn" style="margin-top:15px" onclick="nav('pockets')">Gerenciar</button></div></div>`}
function chartRows(groups){const arr=Object.entries(groups).sort((a,b)=>b[1].n-a[1].n);return arr.map(([name,g])=>`<div style="padding:13px 0;border-bottom:1px solid #eceeea"><div style="display:flex;justify-content:space-between;gap:12px;font-size:11px"><b>${esc(name)}</b><span>${g.ok}/${g.n} · ${Math.round(g.ok/g.n*100)}%</span></div><div style="height:7px;margin-top:10px;border-radius:5px;background:#ebefeb"><div style="height:100%;background:#187459;width:${Math.round(g.ok/g.n*100)}%;border-radius:5px"></div></div></div>`).join('')}
function groupStats(by){const x={};for(const a of attempted()){const k=a[by]||'Outro';x[k]=x[k]||{ok:0,n:0};x[k].n++;if(a.ok)x[k].ok++}return x}
function renderStats(){hubBox().innerHTML=sectionTitle('MEU DESEMPENHO','Estatísticas','Indicadores calculados a partir das suas respostas nesta demo.')+`<div class="kpis"><div class="glass kpi"><b>${attempted().length}</b><span>respostas</span></div><div class="glass kpi"><b>${accuracy()}%</b><span>acerto geral</span></div><div class="glass kpi"><b>${wrongAttempts().length}</b><span>erros registrados</span></div><div class="glass kpi"><b>${fmtSec(STUDY.seconds||0)}</b><span>foco acumulado</span></div></div><div class="glass adminBlock" style="margin-top:14px"><span class="eyebrow">Desempenho por matéria</span>${chartRows(groupStats('subject'))||emptyBox('Ainda sem estatísticas','Responda questões para iniciar a análise.')}</div>`}
function renderWeak(){const rows=Object.entries(groupStats('subject')).sort((a,b)=>(a[1].ok/a[1].n)-(b[1].ok/b[1].n));hubBox().innerHTML=sectionTitle('MEU DESEMPENHO','Pontos fracos','As matérias com menor índice de acerto no histórico local.')+`<div class="glass adminBlock">${rows.length?rows.map(([name,v],i)=>`<div class="quickItem" style="margin-bottom:9px"><div><b>${i+1}. ${esc(name)}</b><div class="soft" style="font-size:9px;margin-top:5px">${v.n} respostas realizadas</div></div><span class="pill ${v.ok/v.n<.6?'amber':'green'}">${Math.round(v.ok/v.n*100)}%</span></div>`).join(''):emptyBox('Sem pontos fracos identificados','Responda questões para começar esta avaliação.')}</div>`}
function renderDNA(){hubBox().innerHTML=sectionTitle('MEU DESEMPENHO','DNA da prova','Veja seu desempenho por formato de exercício, sem estimativas inventadas.')+`<div class="glass adminBlock"><span class="eyebrow">ACERTO POR TIPO</span>${chartRows(groupStats('type'))||emptyBox('Sem dados por formato','Faça um treino misto para conhecer seu desempenho.')}</div>`}
function renderMentoring(){const g=groupStats('subject'),w=Object.entries(g).filter(([_,v])=>v.n>0).sort((a,b)=>a[1].ok/a[1].n-b[1].ok/b[1].n)[0];hubBox().innerHTML=sectionTitle('MEU DESEMPENHO','Mentoria semanal','Orientações automáticas demonstrativas geradas apenas do seu desempenho local.')+`<div class="grid2"><div class="glass adminBlock"><span class="eyebrow">PRIORIDADE</span><h3 style="font-size:21px;margin:13px 0">${w?esc(w[0]):'Faça seu primeiro treino'}</h3><p class="soft" style="font-size:11px;line-height:1.75">${w?'Seu índice de acerto nesta matéria é de '+Math.round(w[1].ok/w[1].n*100)+'%. Comece revisando os erros antes de novas questões.':'Ainda não há tentativas suficientes para sugerir um foco baseado em dados.'}</p><button class="btn primary" style="margin-top:16px" onclick="nav('${w?'errors':'questions'}')">${w?'Revisar erros':'Começar treino'}</button></div><div class="glass adminBlock"><span class="eyebrow">ROTINA SUGERIDA</span><div class="stack" style="margin-top:12px">${['Revisar uma aula base','Responder questões do tema','Transformar erros em flashcards','Fazer revisão curta no dia seguinte'].map((x,i)=>`<div class="quickItem"><span>${i+1}. ${x}</span></div>`).join('')}</div></div></div>`}
function renderStudyTogether(){hubBox().innerHTML=sectionTitle('COMUNIDADE · SINUS','Estudar junto','Compartilhe uma sessão de estudo e convide colegas. Conexão entre contas será habilitada na versão publicada.')+`<div class="glass adminBlock" style="max-width:760px"><h3 style="font-size:19px">Seu grupo de estudo</h3><p class="soft" style="font-size:11px;margin:12px 0">Você pode copiar uma mensagem pronta para convidar seu grupo.</p><textarea id="inviteText" rows="4">Vamos estudar Medicina pelo Sinus! Podemos combinar uma sessão de revisão com questões, materiais e um cronograma da nossa turma.</textarea><button class="btn primary" style="margin-top:12px" onclick="copyInvite()">Copiar convite</button></div>`}
function copyInvite(){const t=$('inviteText').value;if(navigator.clipboard){navigator.clipboard.writeText(t).then(()=>toast('Convite copiado')).catch(()=>{ $('inviteText').select();document.execCommand('copy');toast('Convite selecionado')})}else{$('inviteText').select();document.execCommand('copy');toast('Convite copiado')}}
function renderRanking(){const d=Date.now()-7*86400000,week=attempted().filter(x=>new Date(x.date).getTime()>=d),points=week.length*10;hubBox().innerHTML=sectionTitle('COMUNIDADE · META PESSOAL','Ranking de estudos','Nesta demo offline exibimos somente seu desempenho pessoal, sem participantes ou classificações fictícias.')+`<div class="grid2"><div class="glass adminBlock"><span class="eyebrow">ÚLTIMOS SETE DIAS</span><h2 style="font-size:48px;margin:10px 0">${points} <span style="font-size:12px">PTS</span></h2><p class="soft" style="font-size:11px">${week.length} de 20 questões para participar de uma futura classificação.</p><div style="height:8px;background:#ebefeb;border-radius:5px;margin:17px 0"><div style="height:100%;width:${Math.min(100,week.length*5)}%;background:#177353;border-radius:5px"></div></div><button class="btn primary" onclick="nav('questions')">Responder questões</button></div><div class="glass adminBlock"><span class="eyebrow">SEU PLACAR</span><h2 style="font-size:22px;margin:10px 0">${esc(user().name)}</h2><p class="soft" style="font-size:11px;line-height:1.7">Um ranking nacional verdadeiro exige contas autenticadas e banco central de pontos. Aqui, a interface e a meta já estão prontas para testarmos.</p></div></div>`}
