answerTraining=function(ans){const t=UI.training,q=t?.questions?.[t.index];if(q&&!t.answered){const ok=q.type==='flashcard'?ans!=='__hard__':q.type==='match'||String(ans||'').trim().toLowerCase()===String(q.answer||'').trim().toLowerCase();STUDY.attempts.push({id:q.id,subject:q.subject,type:q.type,ok,date:new Date().toISOString(),tag:'subject'});studySave()}return _sinusalAnswerTrainingBase(ans)};
