function renderDigitalSchedule(c){const data=DB.schedules?.[c];if(!data)return '';const days=data.dias||{};return `<div style="margin-top:20px"><div class="heading"><div><span class="eyebrow">GRADE DIGITAL · 5º PERÍODO</span><h1 style="font-size:22px">Aulas estruturadas da turma ${esc(c)}</h1><p>Mostra somente os registros já transcritos. Confira a imagem oficial acima para grupos e práticas adicionais.</p></div></div><div class="weekGrid">${WEEK_KEYS.map(day=>`<div class="glass dayCol"><span class="eyebrow">${day.toUpperCase()}</span><h3>${WEEK_NAMES[day]}</h3>${(days[day]||[]).map(ev=>`<div class="slot"><span class="time">${esc(ev.time||'')}</span><b>${esc(ev.mat||'')}</b><small>${esc(ev.prof||'')}</small><small><span class="pill ${ev.tipo==='p'?'green':''}">${ev.tipo==='p'?'Prática':'Teoria'}</span> ${ev.gp?`<span class="pill">${esc(ev.gp)}</span>`:''} ${esc(ev.loc||'')}</small></div>`).join('')||'<p class="soft" style="font-size:9px">Sem registros.</p>'}</div>`).join('')}</div></div>`}
