function renderAdminSchedules(){const cat=DB.driveCatalog||DRIVE_CATALOG,classes=Object.keys(cat.periods?.[ADMSCH.period]||{});if(!classes.includes(ADMSCH.className))ADMSCH.className=classes[0]||'A';const files=cat.periods?.[ADMSCH.period]?.[ADMSCH.className]||[];const digital=DB.schedules?.[ADMSCH.className];$('admin-schedules').innerHTML=sectionTitle('FONTE · DRIVE','Horários e grades oficiais','O catálogo original do Drive está incorporado à demo. Você também pode acrescentar uma imagem, prática ou horário estruturado.',`<button class="btn primary" onclick="saveDB()">Salvar ajustes</button>`)+`<div class="glass adminBlock"><div class="controlRow"><select style="width:auto" onchange="ADMSCH.period=this.value;renderAdminSchedules()">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${ADMSCH.period===String(i+1)?'selected':''}>${i+1}º período</option>`).join('')}</select><select style="width:auto" onchange="ADMSCH.className=this.value;renderAdminSchedules()">${classes.map(c=>`<option ${c===ADMSCH.className?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn primary sm" onclick="newScheduleSource()">+ Adicionar arquivo Drive</button></div><div class="stack" style="margin-top:14px">${files.map((f,i)=>`<div class="quickItem"><div><b>${esc(f.name)}</b><div class="soft" style="font-size:9px;margin-top:5px">${esc(f.kind)} · ${esc(f.id)}</div></div><div class="controlRow"><a href="https://drive.google.com/file/d/${f.id}/view" target="_blank" class="btn sm" style="text-decoration:none">Abrir</a><button class="btn sm" onclick="removeScheduleSource(${i})">Excluir</button></div></div>`).join('')||emptyBox('Sem fontes','Adicione um arquivo do Drive.')}</div></div><div class="glass adminBlock" style="margin-top:14px"><span class="eyebrow">GRADE DIGITAL · 5º PERÍODO</span><h3 style="font-size:16px;margin:10px 0">Editar aulas estruturadas</h3><div class="controlRow"><select id="adDay" style="width:auto" onchange="ADMSCH.day=this.value;renderAdminSchedules()">${WEEK_KEYS.map(d=>`<option value="${d}" ${d===ADMSCH.day?'selected':''}>${WEEK_NAMES[d]}</option>`).join('')}</select><button class="btn sm primary" onclick="newDigitalEvent()" ${ADMSCH.period!=='5'?'disabled':''}>+ Inserir aula digital</button></div><div class="stack" style="margin-top:12px">${ADMSCH.period==='5'&&(digital?.dias?.[ADMSCH.day]||[]).length?(digital.dias[ADMSCH.day]||[]).map((e,i)=>`<div class="quickItem"><div><b>${esc(e.time||'')} · ${esc(e.mat||'')}</b><div class="soft" style="font-size:9px;margin-top:5px">${e.tipo==='p'?'Prática':'Teoria'} · ${esc(e.prof||'')}</div></div><button class="btn sm" onclick="removeDigitalEvent(${i})">Excluir</button></div>`).join(''):'<p class="soft" style="font-size:11px">Visualização e edição digital disponíveis apenas para registros já transcritos do 5º período.</p>'}</div></div>`}
function newScheduleSource(){openModal('Nova fonte original',`<label class="field"><span>Nome do arquivo</span><input id="scName" placeholder="6º A · Prática G1"></label><label class="field"><span>Tipo</span><select id="scKind"><option value="original">Grade completa</option><option value="theory">Teórica</option><option value="practice-G1">Prática G1</option><option value="practice-G2">Prática G2</option><option value="practice-G3">Prática G3</option></select></label><label class="field"><span>ID do arquivo Drive</span><input id="scId" placeholder="Google Drive FILE_ID"></label>`,()=>{const id=$('scId').value.trim();if(!id)return toast('Informe o ID');DB.driveCatalog.periods[ADMSCH.period]=DB.driveCatalog.periods[ADMSCH.period]||{};DB.driveCatalog.periods[ADMSCH.period][ADMSCH.className]=DB.driveCatalog.periods[ADMSCH.period][ADMSCH.className]||[];DB.driveCatalog.periods[ADMSCH.period][ADMSCH.className].push({id,name:$('scName').value||'Novo horário',kind:$('scKind').value});saveDB();closeModal();renderAdminSchedules()})}
function removeScheduleSource(i){if(!confirm('Remover somente do catálogo local desta demo?'))return;DB.driveCatalog.periods[ADMSCH.period][ADMSCH.className].splice(i,1);saveDB();renderAdminSchedules()}
function newDigitalEvent(){if(ADMSCH.period!=='5')return;openModal('Nova aula digital',`<div class="grid2"><label class="field"><span>Horário</span><input id="evTime" placeholder="14:00-16:00"></label><label class="field"><span>Matéria</span><input id="evMat"></label></div><label class="field"><span>Professor</span><input id="evProf"></label><div class="grid2"><label class="field"><span>Tipo</span><select id="evType"><option value="t">Teoria</option><option value="p">Prática</option></select></label><label class="field"><span>Grupo</span><input id="evGroup" placeholder="G1 / G2 / etc"></label></div><label class="field"><span>Local</span><input id="evLocal"></label>`,()=>{const data=DB.schedules[ADMSCH.className];if(!data)return toast('Turma digital não cadastrada');data.dias=data.dias||{};data.dias[ADMSCH.day]=data.dias[ADMSCH.day]||[];data.dias[ADMSCH.day].push({time:$('evTime').value,mat:$('evMat').value,prof:$('evProf').value,tipo:$('evType').value,gp:$('evGroup').value,loc:$('evLocal').value});saveDB();closeModal();renderAdminSchedules()})}
function removeDigitalEvent(i){DB.schedules[ADMSCH.className].dias[ADMSCH.day].splice(i,1);saveDB();renderAdminSchedules()}
