/* SINUS v11 — two independent learning contexts, one study center. */
const V11_CATS=['slides','provas','audios','videos','pratica','complementares'];
const V11_SUBJECT_TABS={
 theory:[['overview','Visão geral'],['slides','Slides'],['provas','Provas'],['audios','Áudios'],['videos','Vídeos'],['complementares','Complementares'],['transcribe','Transcrever'],['training','Treino'],['review','Revisão e progresso'],['notebook','Caderno']],
 practice:[['overview','Visão geral'],['pratica','Aulas práticas'],['laminas','Lâminas e imagens'],['provas','Provas práticas'],['audios','Áudios práticos'],['videos','Vídeos práticos'],['complementares','Complementares'],['transcribe','Transcrever'],['training','Treino prático'],['review','Revisão e progresso'],['notebook','Caderno']]
};
function v11InferredMode(cat,item){
 if(item.studyMode==='theory'||item.studyMode==='practice')return item.studyMode;
 if(cat==='pratica')return 'practice';
 const title=String(item.title||'')+' '+String(item.kind||'');
 // Only explicit markers identify old practical files; everything else stays in its original theory archive.
 if(/\b(pr[aá]tica|pr[aá]ctico|pr[aá]cticas|l[aá]mina|l[aá]minas|macroscop[ií]a|taller|laboratorio|exame f[ií]sico.*demonstra)/i.test(title))return 'practice';
 // The Chamorro final review videos were sourced from the practical Drive archive.
 if(cat==='videos'&&['1b0iyFmhnjNQ2_KsxJ6TqBGtMqRzNt_rw','18HoUxwcxZHxDTloaQ1dVQ7YQKVuYv5FD','1p_y9BmxuNG3jxWpFqrmcQC2qTZ4p6fZo'].includes(item.id))return 'practice';
 return 'theory';
}
function v11Section(cat,item){
 if(item.studySection)return item.studySection;
 if(cat==='pratica')return /l[aá]mina|macroscop|imagem|imagen|semana/i.test(String(item.title||'')+' '+String(item.kind||''))?'laminas':'pratica';
 return cat;
}
function v11Initialize(){
 DB.training=DB.training||{types:[],questions:[],defaults:{}};
 for(const [name,s] of Object.entries(DB.subjects||{})){
  for(const cat of V11_CATS){
   s[cat]=Array.isArray(s[cat])?s[cat]:[];
   s[cat].forEach((item,i)=>{
    if(!item.studyMode)item.studyMode=v11InferredMode(cat,item);
    if(!item.studySection)item.studySection=v11Section(cat,item);
    if(!item.uid)item.uid='v11_'+cat+'_'+i+'_'+(item.id||name).replace(/\W/g,'').slice(0,24);
   });
  }
 }
 // Migrate only old exercise attempts: determine area from the question itself, not the last opened screen.
 (STUDY.attempts||[]).forEach(a=>{if(!a.mode){const q=getQ(a.id);a.mode=q?.mode==='practice'?'practice':'theory'}});
}
v11Initialize();
function v11Assets(name=UI.subject,mode=UI.mode){
 const subject=DB.subjects[name];const out=[];if(!subject)return out;
 for(const cat of V11_CATS){(subject[cat]||[]).forEach((item,index)=>{
  if(item.active===false)return;
  const area=v11InferredMode(cat,item);
  if(area!==mode)return;
  // Evita que materiais exclusivos de outra turma apareçam nos players nativos.
  const own=String(user()?.class||'').trim().toUpperCase();
  const tagged=String(item.cohort||item.class_name||item.className||'').trim().toUpperCase()||(String(item.period||'').match(/\bTurma\s+([A-Z]{1,3})\b/i)?.[1]||'').toUpperCase();
  if(tagged&&(!own||tagged!==own))return;
  out.push({cat,index,item,area,section:v11Section(cat,item)});
 })}
 return out;
}
function v11List(tab){return v11Assets().filter(a=>a.section===tab||(tab==='pratica'&&a.section==='pratica')||(tab==='laminas'&&a.section==='laminas'))}
function v11Counts(){const a=v11Assets();return {materials:a.filter(f=>['slides','pratica','laminas','complementares'].includes(f.section)).length,provas:a.filter(f=>f.section==='provas').length,audios:a.filter(f=>f.section==='audios').length,videos:a.filter(f=>f.section==='videos').length}}
function v11SafeCall(name,mode=UI.mode,tab='overview'){
 if(!DB.subjects[name])return toast('Matéria não encontrada');
 openSubject(name);if(mode!=='theory')setSubjectMode(mode);if(tab!=='overview')setTab(tab)
}
function v11ContextTag(){return UI.mode==='practice'?'PRÁTICA':'TEORIA'}
function v11NoteKey(){return 'sinusal_v11_note_'+UI.subject+'_'+UI.mode}
function v11TransKey(){return 'sinusal_v11_trans_'+UI.subject+'_'+UI.mode}
